    ("Verify", "verifay", "Doğrulamak, Teyit Etmek", "verb", ["confirm", "validate", "substantiate"], ["refute"]),
    ("Versatile", "vöösıtayl", "Çok Yönlü, Çok Amaçlı Kullanılabilen", "adjective", ["adaptable", "all-round", "flexible"], ["rigid", "limited"]),
    ("Vessel", "vesl", "Gemi, Tekne; Kan Damarı", "noun", ["ship", "boat", "vein"], []),
    ("Viable", "vaybıl", "Uygulanabilir, Yaşayabilir, Geçerli", "adjective", ["feasible", "workable", "sustainable"], ["unviable"]),
    ("Vigorous", "vigırıs", "Güçlü, Enerjik, Dinamik, Sağlam", "adjective", ["energetic", "forceful", "robust"], ["frail", "feeble"]),
    ("Virtually", "vöörçuıli", "Hemen Hemen, Neredeyse, Adeta", "adverb", ["practically", "nearly", "almost"], []),
    ("Vital", "vaytl", "Hayati, Çok Önemli, Yaşamsal", "adjective", ["crucial", "essential", "indispensable"], ["trivial"]),
    ("Volatile", "volıtayl", "Değişken, Uçucu, Çalkantılı", "adjective", ["unstable", "fickle", "erratic"], ["stable", "calm"]),
    ("Vulnerable", "valnırbıl", "Savunmasız, Hassas, Kırılgan", "adjective", ["susceptible", "fragile", "exposed"], ["invulnerable"]),
    ("Welfare", "welfeyır", "Refah, Esenlik, Sosyal Yardım", "noun", ["well-being", "prosperity", "benefit"], []),
